import feign.Client
import javax.net.ssl.HostnameVerifier
import javax.net.ssl.SSLSocketFactory
class BadFeignClient {
    fun bad(socketFactory: SSLSocketFactory, hostnameVerifier: HostnameVerifier): Client {
        return Client.Default(socketFactory, hostnameVerifier) // bad
    }
}

import feign.Client
class GoodDefaultFeignClient {
    fun good(): Client {
        return Client.Default(null, null)
    }
}

import feign.Client
import feign.okhttp.OkHttpClient
class GoodOkHttpFeignClient {
    fun good(): Client {
        return OkHttpClient()
    }
}
